content.text:
{
  "Q1": {
    "q1_duty_procs": {
      "verdict": "yes",
      "rationale": "Table lists 11046 (2026-14991, 91 FR 46639), 11047 (2026-14992, 91 FR 46653), 11048 (2026-14997, 91 FR 46663), each signed July 20, 2026 and published July 23, 2026."
    },
    "q1_details": {
      "verdict": "yes",
      "rationale": "All ten documents carry the correct first page (46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) and an accurate one-line description."
    },
    "q1_delay": {
      "verdict": "yes",
      "rationale": "Lists 11056 (2026-17294, 91 FR 54789), signed August 18 and published August 24, 2026, and says it moved the three duties to 12:01 a.m. August 22 (from the original August 19)."
    },
    "q1_exclusions": {
      "verdict": "yes",
      "rationale": "Lists 11061/11062/11063 (2026-18835/-18836/-18837; 91 FR 58311/58319/58325), signed September 8, published September 14, 2026, with operative time 12:01 a.m. September 29, 2026."
    },
    "q1_scope": {
      "verdict": "yes",
      "rationale": "Lists 11064 (2026-18838) and 11065 (2026-18839), signed September 8 and applying from 12:01 a.m. September 15; and 11076 (2026-22292), signed October 23, published October 30, applying from 12:01 a.m. October 30, 2026."
    },
    "q1_events": {
      "verdict": "yes",
      "rationale": "The table measures the duty/scope changes against 'entered for consumption or withdrawn from warehouse' and the exclusions against 'importation' and 'measured against importation, not consumption entry.'"
    },
    "q1_dairy_none": {
      "verdict": "yes",
      "rationale": "Q1(b) says alcohol was modified by 11064, motor vehicles by 11065/11076, and for dairy: '11047 imposed; 11056 delayed; 11062 excluded its Annex products; no separate dairy scope-modification proclamation appears in this series.'"
    },
    "q1_dairy_xref": {
      "verdict": "no",
      "rationale": "The answer says no separate dairy scope modification appears, but never notes that 11062 clause (3) refers to a September 8, 2026 proclamation modifying the dairy duty scope, nor that the referenced document is absent from the Federal Register. The clause-3 cross-reference is missing."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "The table and basis give document numbers, FR pages and clause numbers for essentially every claim; citation discipline is met."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "Checked the principal citations (2026-14991/14992/14997, 2026-17294, 2026-18835-18839, 2026-22292 and pages 46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) against the key; no invented document, page or clause appears."
    }
  },
  "Q2": {
    "q2a_zero": {
      "verdict": "yes",
      "rationale": "Entry 1 (August 20, 2:00 p.m.) and entry 2 (11:59 p.m. August 21) are both answered $0."
    },
    "q2a_third": {
      "verdict": "yes",
      "rationale": "Entry 3 (12:01 a.m. August 22) is '$40,000 × 50% = $20,000.'"
    },
    "q2a_basis": {
      "verdict": "yes",
      "rationale": "Answer relies on '11056 clause (1) changes the effective date to August 22,' and basis cites Proclamation 11056, clauses (1) and (4), 91 FR 54790-91 (2026-17294)."
    },
    "q2b_chapeau": {
      "verdict": "yes",
      "rationale": "Says 11056 'did not edit the numbered paragraphs (1) and (3) of Proclamation 11046, which still print August 19' and 'expressly amends the chapeau of Annex II, deleting \"August 19\" and inserting \"August 22.\"'"
    },
    "q2b_resolve": {
      "verdict": "yes",
      "rationale": "Says 11056 clause (1) itself changes the effective date to August 22, and that read together the later amendment/operative account resolve the older printed August 19 in favor of August 22 (the first-sentence resolution)."
    },
    "q2c_refund": {
      "verdict": "yes",
      "rationale": "Cites 11056 clause (4): refunds, to the extent implementation requires them, are processed 'under applicable law and CBP's standard procedures.' It correctly does not say the documents are silent."
    },
    "q2d_no_action": {
      "verdict": "yes",
      "rationale": "Says no further presidential action was made a condition, that 11056 set August 22, and that later proclamations state the three-day suspension lapsed at 12:01 a.m. ET August 22 when the duties became effective."
    },
    "q2d_reneged": {
      "verdict": "yes",
      "rationale": "Says later proclamations state Canada reneged on its commitment on August 21, 2026, which is the required date and fact."
    },
    "q2e_thirty": {
      "verdict": "yes",
      "rationale": "Explains August 19 from the 30-day rule: signed July 20, counting July 21 as day 1 makes August 19 day 30; it also distinguishes signing from FR publication."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "Claims are tied to proclamation clauses and FR pages throughout (e.g., 11046 clauses 9-10 and (1), 91 FR 46640-41; 11056 clauses (1), (4), 91 FR 54790-91)."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation; the quoted/paraphrased 11056 clause (1) and (4) material corresponds to the key's text."
    }
  },
  "Q3": {
    "q3a_shipment_a": {
      "verdict": "yes",
      "rationale": "A: 'May be imported; $15,000,' with September 10 import before the exclusion and September 14 entry before the scope change."
    },
    "q3a_shipment_b": {
      "verdict": "yes",
      "rationale": "B: 'May be withdrawn; $15,000,' because imported before September 29 and unentered, invoking 11061 clause (2)'s preservation of the 50% duty."
    },
    "q3a_shipment_c": {
      "verdict": "yes",
      "rationale": "C: 'May be entered; $15,000,' because imported at 11:30 p.m. September 28 before the importation cutoff; the September 29 entry does not make it excluded."
    },
    "q3a_shipment_d": {
      "verdict": "yes",
      "rationale": "D: 'It is excluded from importation; no lawful consumption entry is available,' because arrival at 12:30 a.m. September 29 is on/after 12:01 a.m. September 29."
    },
    "q3b_result": {
      "verdict": "yes",
      "rationale": "E: not excluded, and '$15,000 on withdrawal' on October 6 because it was imported September 25 and had not been entered for consumption before September 29 (11061 clause (2))."
    },
    "q3b_ftz": {
      "verdict": "yes",
      "rationale": "Cites the FTZ rule: admitted September 25, after the duty's effective date, it 'must be in privileged foreign status unless eligible for domestic status'; basis cites 11046 clause (4), 91 FR 46641."
    },
    "q3c_invalid": {
      "verdict": "yes",
      "rationale": "Says 11061 clause (9)(b) makes the 50% duty under 11046 apply to imports to which the invalidated ban had applied; correctly does not make the goods duty-free."
    },
    "q3d_no_change": {
      "verdict": "yes",
      "rationale": "Says no: 11061 clause (3) 'does not otherwise affect the other products subject to the duty,' so listed products outside the exclusion Annex remain at 50%."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "Each part cites 11061 clauses (1)-(3), (9)(b), 91 FR 58312-13, and 11046 clauses (1), (4), 91 FR 46641."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "The quotations and clause references are real; no fabricated document, page or provision appears."
    }
  },
  "Q4": {
    "q4a_amounts": {
      "verdict": "yes",
      "rationale": "For September 10, X, Y and Z each get section 232 $25,000 and section 338 $0."
    },
    "q4a_basis": {
      "verdict": "yes",
      "rationale": "Q4(c) and the basis rely on clause (2) of 11046/11047/11048 ('shall not apply to articles subject to duties pursuant to section 232'), 91 FR 46641, 46655, 46665."
    },
    "q4b_x": {
      "verdict": "yes",
      "rationale": "X on October 1: section 232 $25,000 and section 338 $50,000, because 11064 clause (1) makes the 11046 duty apply in addition to section 232 from September 15."
    },
    "q4b_z": {
      "verdict": "yes",
      "rationale": "Z on October 1: section 232 $25,000 and section 338 $50,000, because 11065 clause (1) makes the 11048 duty apply in addition to section 232 from September 15."
    },
    "q4b_y": {
      "verdict": "no",
      "rationale": "Y is given section 338 $50,000, but no document modified Proclamation 11047; its clause (2) carve-out still applies, so the correct section 338 duty is $0. The criterion expressly makes a $50,000 answer for Y wrong."
    },
    "q4c_text": {
      "verdict": "yes",
      "rationale": "Identifies both clause (2) of the duty proclamations and the 11064/11065 clause (1) 'in addition to' sentence effective for entries on or after 12:01 a.m. September 15, 2026."
    },
    "q4c_supersede": {
      "verdict": "yes",
      "rationale": "The answer cites both provisions with FR pages and applies the later stacking clause from September 15 (September 10 only section 232; October 1 both layers), which the criterion's safe-harbor sentence accepts."
    },
    "q4c_xref": {
      "verdict": "no",
      "rationale": "Does not mention 11062 clause (3)'s reference to a September 8, 2026 dairy scope proclamation, nor that no such proclamation exists."
    },
    "q4c_doubt": {
      "verdict": "no",
      "rationale": "Presents all six results as settled and gives Y $50,000; there is no qualification or doubt about the missing dairy modification."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "Clause and page citations are supplied for each layer (11046/11047/11048 clause (2); 11064/11065 clause (1))."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "The provisions and pages cited are real; the Y error is a substantive misapplication, not fabrication."
    }
  },
  "Q5": {
    "q5a_p": {
      "verdict": "yes",
      "rationale": "P: No on September 14 3:00 p.m.; Yes at September 15 12:01 a.m., October 29 4:00 p.m., October 30 12:01 a.m. and November 3."
    },
    "q5a_q": {
      "verdict": "yes",
      "rationale": "Q: Yes on September 14; No at the other four times, because 11065 Part B removes it from September 15."
    },
    "q5a_r": {
      "verdict": "yes",
      "rationale": "R: Yes on September 14, September 15 and October 29; No on October 30 and November 3, because 11076 Part A products 'shall no longer be subject.'"
    },
    "q5a_s": {
      "verdict": "yes",
      "rationale": "S: No for the first three times; Yes on October 30 12:01 a.m. and November 3, because 11076 Part B products 'shall be subject.'"
    },
    "q5b_dates": {
      "verdict": "yes",
      "rationale": "11076 signed October 23, filed October 29 (11:15 a.m.), published October 30, applies from 12:01 a.m. October 30, 2026."
    },
    "q5b_prospective": {
      "verdict": "yes",
      "rationale": "Says 11076 'does not say that its scope changes apply to earlier entries and does not provide refunds'; the scope proclamations are applied only prospectively."
    },
    "q5c_days": {
      "verdict": "yes",
      "rationale": "P: September 8 to September 15 = seven days; S: October 23 to October 30 = seven days."
    },
    "q5c_silent": {
      "verdict": "yes",
      "rationale": "Says the scope proclamations 'do not expressly explain how those seven-day scope changes relate to section 338's stated 30-day period' and that the texts do not resolve the issue."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "Each row and part is tied to 11065/11076 clauses and pages (91 FR 58340, 68862-63) and 11048/11056."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented source; the filing time, dates and clause references match the key."
    }
  },
  "Q6": {
    "q6a_switzerland": {
      "verdict": "yes",
      "rationale": "Switzerland: $100,000 × 8.5% = $8,500; total $12,500."
    },
    "q6a_norway": {
      "verdict": "yes",
      "rationale": "Norway: $12,500 flat; total $16,500."
    },
    "q6a_uk": {
      "verdict": "yes",
      "rationale": "United Kingdom: $10,000; total $14,000."
    },
    "q6a_germany": {
      "verdict": "yes",
      "rationale": "Germany/EU: $6,000 (10% − 4%); total $10,000."
    },
    "q6a_taiwan": {
      "verdict": "yes",
      "rationale": "Taiwan: $6,000; total $10,000."
    },
    "q6a_turkiye": {
      "verdict": "yes",
      "rationale": "Türkiye: $12,500; total $16,500."
    },
    "q6a_japan": {
      "verdict": "yes",
      "rationale": "Japan: $8,500 (12.5% − 4%); total $12,500."
    },
    "q6a_liechtenstein": {
      "verdict": "yes",
      "rationale": "Liechtenstein: $0 because it is not one of the 60 investigated economies; total $4,000."
    },
    "q6a_hongkong": {
      "verdict": "yes",
      "rationale": "Hong Kong: $12,500 flat; total $16,500."
    },
    "q6a_india": {
      "verdict": "yes",
      "rationale": "India: $10,000 flat; total $14,000."
    },
    "q6b_germany12": {
      "verdict": "yes",
      "rationale": "Germany with 12% MFN: $0, because the MFN rate is at least the 10% target."
    },
    "q6b_japan12": {
      "verdict": "yes",
      "rationale": "Japan with 12% MFN: $100,000 × 0.5% = $500."
    },
    "q6b_taiwan10": {
      "verdict": "yes",
      "rationale": "Taiwan with exactly 10% MFN: $0 under the 'greater than or equal to' rule."
    },
    "q6b_korea10": {
      "verdict": "yes",
      "rationale": "South Korea with exactly 10% MFN: $2,500 (12.5% − 10%)."
    },
    "q6b_swiss_free": {
      "verdict": "yes",
      "rationale": "Switzerland duty-free: $12,500 (full 12.5%)."
    },
    "q6c_net": {
      "verdict": "yes",
      "rationale": "Identifies Switzerland, Japan, Germany/EU and Taiwan as changed from flat proposal rates to net-of-MFN rates; correctly leaves Norway, UK, Türkiye and Hong Kong unchanged."
    },
    "q6c_india": {
      "verdict": "yes",
      "rationale": "Says India was proposed at 12.5% and adopted at 10% after adopting a forced-labor import prohibition after the June proposal."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "Rates are cited to memorandum sec. 1(a), 91 FR 47720, and notice pages 47320-28."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No invented source; the rate categories and the India reason appear in the cited materials."
    }
  },
  "Q7": {
    "q7a_france": {
      "verdict": "yes",
      "rationale": "France: $60 duty, 0.5% equivalent, 9.5% section 301 rate, $1,140 duty."
    },
    "q7b_italy": {
      "verdict": "yes",
      "rationale": "Italy: $1,800 MFN, 9% equivalent, 1% section 301, $200."
    },
    "q7b_japan": {
      "verdict": "yes",
      "rationale": "Japan: 12.5% − 9% = 3.5%, $700."
    },
    "q7b_brazil": {
      "verdict": "yes",
      "rationale": "Brazil: flat 12.5%, $2,500, with no conversion or cap."
    },
    "q7c_taiwan": {
      "verdict": "yes",
      "rationale": "Taiwan: 11% equivalent is at/above the 10% cap, so $0."
    },
    "q7c_switzerland": {
      "verdict": "yes",
      "rationale": "Switzerland: 12.5% − 11% = 1.5%, $300."
    },
    "q7d_note": {
      "verdict": "yes",
      "rationale": "Identifies U.S. note 52(k), 91 FR 47394, for dividing column 1-General duty by customs value to get the ad valorem equivalent."
    },
    "q7d_zero": {
      "verdict": "no",
      "rationale": "Answer (d) says 'The same note states ... the additional section 301 duty is zero,' and the basis cites only note 52(k). Note 52(k) at 91 FR 47394 states only the less-than case; the zero-at-or-above-cap rule is in memorandum sec. 1(a)(ii) and the notice determinations (91 FR 47320-21, 47323-27). The criterion expressly says no when the zero result is attributed to note 52(k)."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "Each calculation cites note 52(k) and the economy determinations."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "The mislocation of the zero rule is a misreading of real provisions, not fabrication; no invented source."
    }
  },
  "Q8": {
    "q8a_case1": {
      "verdict": "yes",
      "rationale": "Case 1: $10,000, because entry July 29 is after the July 28 transit cutoff."
    },
    "q8a_case2": {
      "verdict": "yes",
      "rationale": "Case 2: $0, because vessel transit before July 24 and entry July 27 before the cutoff."
    },
    "q8a_case3": {
      "verdict": "yes",
      "rationale": "Case 3: $10,000, because entry at 12:01 a.m. July 28 is not 'before' 12:01 a.m. July 28."
    },
    "q8a_case4": {
      "verdict": "yes",
      "rationale": "Case 4: $10,000, because loading at 6:00 a.m. July 24 is not before 12:01 a.m. July 24."
    },
    "q8a_case5": {
      "verdict": "yes",
      "rationale": "Case 5: $0, entered July 23 before the duties apply."
    },
    "q8a_case6": {
      "verdict": "yes",
      "rationale": "Case 6: $10,000, withdrawal July 26 after the effective time and not within the vessel-transit exception."
    },
    "q8a_case7": {
      "verdict": "yes",
      "rationale": "Case 7: $10,000; says the exception is limited to goods loaded onto a vessel, so the air shipment does not qualify."
    },
    "q8b_where": {
      "verdict": "yes",
      "rationale": "Places the transit rule in the action notice's DATES line, 91 FR 47318."
    },
    "q8c_dates": {
      "verdict": "yes",
      "rationale": "Memorandum signed July 23, 2026; duties from 12:01 a.m. ET July 24; published July 28, 2026."
    },
    "q8d_july30": {
      "verdict": "yes",
      "rationale": "July 30 entry: $10,000; the July 31 HTSUS modification adding patented pharmaceutical headings is identified."
    },
    "q8d_aug3": {
      "verdict": "yes",
      "rationale": "August 3 entry: $0 under the patented-pharmaceutical exemption effective July 31."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "The DATES line, Annex I.B and the rate source are cited by page."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented source; the transit language and July 31 pharmaceutical date match the key."
    }
  },
  "Q9": {
    "q9a_assembly": {
      "verdict": "yes",
      "rationale": "($100,000 − $35,000) × 12.5% = $8,125 under note 52(a) for 9802.00.80."
    },
    "q9b_repairs": {
      "verdict": "yes",
      "rationale": "$6,000 × 12.5% = $750 for the repair value under 9802.00.50."
    },
    "q9c_usmca": {
      "verdict": "yes",
      "rationale": "Mexico entered free under USMCA: $0 section 301 under note 52(h)."
    },
    "q9c_no_claim": {
      "verdict": "yes",
      "rationale": "Mexico without USMCA claim: $50,000 × 10% = $5,000."
    },
    "q9d_car": {
      "verdict": "yes",
      "rationale": "Passenger car under 9903.94.01: $0 under note 52(f)(2)."
    },
    "q9e_reading": {
      "verdict": "yes",
      "rationale": "Concludes the section 301 duty is $12,500 (12.5% × $100,000) because the unnamed section 232 heading is not among note 52(f)'s listed exceptions."
    },
    "q9e_flag": {
      "verdict": "yes",
      "rationale": "In the same Q9 answer, (f) states that the June proposal would have exempted all articles/parts subject to section 232 while the adopted note provides only specified headings — the required caveat that the documents are not of one mind. It is not repeated under the (e) heading, but it is part of the question's answer/basis."
    },
    "q9f_232": {
      "verdict": "yes",
      "rationale": "Says the proposal described exemptions for all articles/parts subject to section 232, while the adopted note exempts only 'specific section 232 headings/products.'"
    },
    "q9f_info": {
      "verdict": "yes",
      "rationale": "Says the proposal listed informational materials and donations, and the adopted readable text does not provide those blanket exemptions."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Note 52(a), (f), (g), (h) and pages 47352-63, 47394 are cited."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented source; the note citations and effect of the provisions match the key."
    }
  },
  "Q10": {
    "q10a_338": {
      "verdict": "yes",
      "rationale": "September 10 section 338 is $0. Q10(a) gives a timing explanation, but the Q10 answer at (c) states 'The initial section 338 proclamation excluded articles subject to section 232' and the basis cites 11048 clause (2), 91 FR 46665."
    },
    "q10a_301": {
      "verdict": "yes",
      "rationale": "Section 301 $0 because the item is an aluminum article entered under 9903.82.02, citing note 52(f)(1), 91 FR 47362."
    },
    "q10a_total": {
      "verdict": "yes",
      "rationale": "$106,000: MFN $6,000 plus section 232 $100,000."
    },
    "q10b_338": {
      "verdict": "yes",
      "rationale": "September 16: $200,000 × 50% = $100,000, because 11065 clause (1) makes the 11048 duty apply in addition to section 232 from September 15."
    },
    "q10b_total": {
      "verdict": "yes",
      "rationale": "$206,000: MFN $6,000 + section 232 $100,000 + section 338 $100,000 + section 301 $0."
    },
    "q10c_338": {
      "verdict": "yes",
      "rationale": "Under the answer's '(d)' paragraph (lettering shifted), the USMCA rye whisky entry is given section 338 $60,000 × 50% = $30,000; no USMCA exemption is applied."
    },
    "q10c_301": {
      "verdict": "yes",
      "rationale": "Same paragraph: section 301 $0 under note 52(g)'s Canada/USMCA exception; total $30,000."
    },
    "q10d_stack": {
      "verdict": "yes",
      "rationale": "Same paragraph: without USMCA claim, section 338 $30,000 + section 301 $60,000 × 10% = $6,000; total $36,000."
    },
    "q10e_excluded": {
      "verdict": "yes",
      "rationale": "Says the October 2 arrival is prohibited from importation under the September 29 import ban and that no lawful consumption-entry duty total can be calculated."
    },
    "q10f_ieepa": {
      "verdict": "yes",
      "rationale": "Says the IEEPA duties were terminated by Executive Order 14389, signed February 20, 2026; basis cites 91 FR 9437-38 (2026-03832)."
    },
    "q10f_surcharge": {
      "verdict": "yes",
      "rationale": "Says the 10% temporary surcharge ran only through 12:01 a.m. ET July 24, 2026; basis cites Proclamation 11012 clause (7)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "All layers and the (f) documents are cited by proclamation/page."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No invented source; the cited proclamations and executive orders exist and the amounts match aside from the substantive issues scored above."
    }
  },
  "Q11": {
    "q11_valid_1": {
      "verdict": "yes",
      "rationale": "Items in the Q11 answer, in order: (a) the section 338 date mismatch — counted, matching key item 9: 11046/11047/11048 clauses (1) and (3) retain August 19 (91 FR 46641, 46655, 46665) while 11056 clause (1) sets August 22 and amends only the Annex II chapeau (91 FR 54790). (b) the section 232 mismatch — counted, matching key item 5: original clause (2) says 'shall not apply' (46641, 46655, 46665) while 11064/11065 clause (1) say the duties apply 'in addition to' section 232 (58332, 58340) without rewriting clause (2). (c) is not a separate item: it simply says no other readable-text discrepancy was found and that proposal/adopted changes are not themselves discrepancies. Total: 2 valid discrepancies."
    },
